<?php
declare(strict_types=1);
require dirname(__DIR__,2).'/app/bootstrap.php';
if(isset($_SESSION['admin'])&&time()-(int)($_SESSION['last_seen']??0)>1800)unset($_SESSION['admin']);
if(empty($_SESSION['admin'])){http_response_code(403);exit('Inicia sesión desde el panel de administración.');}
$_SESSION['last_seen']=time();
$appRoot=dirname((new ReflectionFunction('db'))->getFileName());
require_once $appRoot.'/DatabaseMaintenance.php';require_once $appRoot.'/DatabaseChangePackage.php';require_once $appRoot.'/SystemHealth.php';require_once $appRoot.'/DatabaseHealthPeriod.php';
$error='';$success='';$report=null;$health=null;$preview=null;$databaseHealth=null;$databasePeriod=null;$databaseIdentity=hash('sha256',(string)$config['dsn']);
try{
    $maintenance=new DatabaseMaintenance(db(),$appRoot,(string)($_SERVER['DOCUMENT_ROOT']??''));
    if($_SERVER['REQUEST_METHOD']==='POST'){
        csrf();$action=$_POST['action']??'';
        if($action==='start_health_period'){
            $reading=SystemHealth::inspect(db(),$config,$appRoot);
            DatabaseHealthPeriod::start(private_storage_path('database-health'),$reading,$databaseIdentity);
            header('Location: base-datos.php?periodo=1#rendimiento',true,303);exit;
        }elseif($action==='validate'){
            unset($_SESSION['db_package']);$upload=$_FILES['package']??[];
            if(($upload['error']??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_OK||!is_uploaded_file($upload['tmp_name']??'')||strtolower(pathinfo($upload['name']??'',PATHINFO_EXTENSION))!=='zip')throw new RuntimeException('Selecciona un paquete ZIP de hasta 2 MB.');
            $ids=DatabaseChangePackage::validate($upload['tmp_name'],$maintenance->migrationCatalog());
            $states=$maintenance->inspect()['migrations'];
            $_SESSION['db_package']=['ids'=>$ids,'expires'=>time()+600,'catalog'=>$maintenance->migrationCatalog(),'states'=>$states];
            $success='Paquete validado. Revisa los cambios antes de confirmar; todavía no se ejecutó SQL.';
        }elseif($action==='apply'){
            $package=$_SESSION['db_package']??null;unset($_SESSION['db_package']);
            if(!is_array($package)||$package['expires']<time()||($_POST['confirmation']??'')!=='APLICAR PAQUETE')throw new RuntimeException('Confirmación inválida o revisión vencida. Valida nuevamente el paquete.');
            if($package['catalog']!==$maintenance->migrationCatalog()||$package['states']!==$maintenance->inspect()['migrations'])throw new RuntimeException('La versión o la estructura cambió. Valida nuevamente el paquete.');
            $results=$maintenance->applyMigrations($package['ids']);
            $success='Paquete procesado. Resultado: '.implode(' · ',array_map(static fn($id,$state)=>$id.': '.$state,array_keys($results),$results));
        }else throw new RuntimeException('Acción no permitida.');
    }
    $report=$maintenance->inspect();$health=$maintenance->health();$requirements=$maintenance->requirementDetails();$preview=$_SESSION['db_package']??null;
}catch(Throwable $e){if(class_exists('PortalIncidents',false))PortalIncidents::technical($e,'base_datos');http_response_code(400);$error=$e instanceof PDOException?'La base rechazó la operación. No repitas automáticamente: revisa el estado y los permisos.':$e->getMessage();if(isset($maintenance)){try{$report=$maintenance->inspect();$health=$maintenance->health();}catch(Throwable){}}}
try{$databaseHealth=SystemHealth::inspect(db(),$config,$appRoot);$databasePeriod=DatabaseHealthPeriod::read(private_storage_path('database-health'),$databaseHealth,$databaseIdentity);}catch(Throwable){}
function db_label(string $state):string{return ['applied'=>'Completo','pending'=>'Falta implementar','partial'=>'Incompleto: revisar antes de continuar'][$state]??'No disponible';}
?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Base de datos | Explorando Lugares</title><link rel="stylesheet" href="../assets/admin.css?v=db-package-picker-20261016"><?php require __DIR__.'/_theme.php'; ?></head><body class="portal-admin"><main class="wrap admin-page"><h1>Base de datos</h1><p>Estructura, índices y cambios de la versión desplegada. Las solicitudes comerciales se gestionan por separado.</p><?php require __DIR__.'/_navigation.php'; ?>
<?php if($error):?><p class="notice health-critical" role="alert"><?=esc($error)?></p><?php endif ?><?php if($success):?><p class="notice" role="status"><?=esc($success)?></p><?php endif ?>
<?php if($report&&$health):?><section class="admin-system"><h2>Estado actual</h2><dl><dt>Conexión</dt><dd>Conectada</dd><dt>Motor real</dt><dd><?=esc($health['engine'])?> · <?=esc($health['version'])?></dd><dt>Controlador de PHP</dt><dd><?=esc($report['driver'])?> (el controlador mysql sirve también para MariaDB)</dd><dt>Tablas encontradas</dt><dd><?=esc($report['tables'])?></dd></dl>
<h3>Todas las tablas e índices</h3><p>Filas y tamaños estimados por el motor; no se leen datos personales. Sin clave primaria es una señal para revisar, no una orden de crear un índice automáticamente. El listado no certifica integridad ni rendimiento de todas las consultas.</p><details><summary>Ver las <?=esc($report['tables'])?> tablas y sus índices</summary><div class="health-table"><table><thead><tr><th>Tabla / motor</th><th>Filas estimadas</th><th>Datos / índices</th><th>Índices y columnas</th><th>Revisión</th></tr></thead><tbody>
<?php foreach($health['tables'] as $row):?><tr><td><?=esc($row['TABLE_NAME'])?><br><?=esc($row['ENGINE'])?></td><td><?=esc($row['TABLE_ROWS']??'No disponible')?></td><td><?=esc(SystemHealth::bytes((float)$row['DATA_LENGTH']))?> / <?=esc(SystemHealth::bytes((float)$row['INDEX_LENGTH']))?></td><td><?php foreach($row['indexes'] as $name=>$columns):?><?=esc($name)?> (<?=esc(implode(', ',$columns))?>)<br><?php endforeach ?></td><td><?=esc($row['warning'])?></td></tr><?php endforeach ?></tbody></table></div></details></section>
<?php require __DIR__.'/_database-health.php'; ?>
<section class="admin-system"><h2>Requisitos de la versión desplegada</h2><p>Se comprueban tablas, columnas y determinados datos de configuración requeridos por cada migración. “Completo” confirma esos controles, no todos los datos del negocio. Si falta un componente, identifica su código, prepara su paquete desde la misma versión y revisa sus dependencias. No se crean tablas al abrir esta página.</p><ul><?php foreach($report['migrations'] as $id=>$state):?><li><details><summary><code><?=esc($id)?></code> · <strong><?=esc(db_label($state))?></strong></summary><ul><?php foreach($requirements[$id]??[] as $requirement):?><li><?=esc($requirement)?></li><?php endforeach ?></ul></details></li><?php endforeach ?></ul></section>
<section class="admin-system db-package-panel"><h2>Cargar un paquete de cambios</h2><p>ZIP con <code>manifest.json</code> y scripts registrados en esta versión. Se rechazan SQL sueltos, archivos .db, scripts desconocidos o modificados y archivos adicionales. El ZIP no se extrae ni se publica. Solo se ejecutan copias verificadas del servidor.</p><form method="post" enctype="multipart/form-data" class="admin-db-action"><input type="hidden" name="csrf" value="<?=esc($_SESSION['csrf'])?>"><input type="hidden" name="action" value="validate"><div class="db-package-field"><p id="db-package-label" class="db-package-label">Paquete de cambios</p><div class="db-package-picker"><label class="db-package-choose"><span>Elegir archivo ZIP</span><input type="file" id="db-package-file" name="package" accept=".zip" aria-label="Elegir archivo ZIP" aria-describedby="db-package-help db-package-name" required></label><span id="db-package-name" role="status" aria-live="polite">Ningún archivo seleccionado</span></div><small id="db-package-help">Formato ZIP · Tamaño máximo: 2 MB. Primero validaremos el contenido; elegir un archivo no ejecuta cambios.</small></div><button class="pill">Validar y ver cambios</button></form>
<?php if(is_array($preview)&&$preview['expires']>=time()):?><h3>Revisión antes de ejecutar</h3><ul><?php foreach($preview['ids'] as $id):?><li><?=esc($id)?> · <?=esc(db_label($report['migrations'][$id]))?></li><?php endforeach ?></ul><p class="notice">DDL en MariaDB puede confirmar cambios de forma automática: no existe una reversión completa garantizada. Mantén una copia de seguridad verificada antes de aplicar. Ante un error se detiene; algunos cambios previos pueden haber quedado aplicados.</p><form method="post" class="admin-db-action"><input type="hidden" name="csrf" value="<?=esc($_SESSION['csrf'])?>"><input type="hidden" name="action" value="apply"><label>Escribe APLICAR PAQUETE<input name="confirmation" required autocomplete="off" pattern="APLICAR PAQUETE"></label><button class="pill">Ejecutar paquete revisado</button></form><?php endif ?>
<p>Formato documentado en el repositorio: <code>docs/PAQUETES_BASE_DATOS.md</code>. Las migraciones se ejecutan en orden; un bloqueo impide que dos paquetes se apliquen simultáneamente desde esta herramienta.</p></section><?php endif ?><script src="../assets/admin-db-package.js?v=20261016-1" defer></script></main></body></html>
